  spreadsheet: { searchLabel: "BÚSQUEDA EN CATÁLOGO ACTIVO", searchTitle: "Usa una frase de producto concreta.", headingIndex: "RUTAS DE CATEGORÍA EXACTAS", headingTitle: "Abre el destino, no una portada genérica.", headingText: "Cada tarjeta abre la categoría correspondiente del catálogo principal activo.", asideLabel: "HOJA / MÉTODO", asideTitle: "Lo que este índice puede demostrar y lo que no.", asideText: "Los términos de Hacoo atribuyen a creadores independientes la responsabilidad del contenido generado por usuarios. Una hoja es una herramienta de descubrimiento, no una aprobación oficial.", items: [["Usa un destino exacto", "Una tarjeta de categoría abre su categoría; una de producto abre una única ficha de detalle."], ["Compara imagen y título", "No basta con que funcione la URL. La primera imagen y el título actuales deben seguir coincidiendo con la tarjeta."], ["Comprueba país y región", "Hacoo afirma admitir 28 países, pero la lista oficial actual nombra 27. Verifica la disponibilidad real en la app."], ["Haz visible la incertidumbre", "Fecha de revisión, estimaciones USD y carácter independiente deben etiquetarse, no presentarse como garantías permanentes."]], source: "Fuentes revisadas: Sobre Hacoo, Términos de servicio, Centro de ayuda oficial sobre zonas de entrega y rutas del catálogo principal · 28 de agosto de 2026." },
  finds: { headingIndex: "DESTINOS DE PRODUCTO COINCIDENTES", headingTitle: "Primera imagen, título y URL revisados juntos.", headingText: "Las tarjetas usan la primera imagen actual de la página de destino exacta. Los USD son conversiones orientativas del precio de origen mostrado.", priceNote: "Referencia: CN¥6,75 = US$1, revisada el 28 de agosto de 2026. Vuelve a comprobar opción, precio de origen y total. Si cambió la imagen o el producto de destino, no continúes desde la tarjeta.", asideLabel: "HALLAZGOS / VERIFICACIÓN", asideTitle: "Un catálogo pequeño puede resultar más útil.", asideText: "El volumen no es señal de calidad. Una tarjeta útil conserva la relación entre descubrimiento y destino activo.", items: [["Ficha exacta", "Ninguna tarjeta conduce a la portada, una búsqueda genérica u otra plataforma."], ["Primera imagen coincidente", "La imagen mostrada aquí es la primera imagen del mismo destino."], ["Precio de origen visible", "La cifra CNY original permanece junto a la estimación en USD."], ["Comprobación de opción actual", "La página de destino manda sobre color, talla, variante, inventario y precio final."]] },
  qc: { asideLabel: "QC / 01—07", asideTitle: "Un orden de inspección repetible", asideText: "Empieza por la vista general y acércate después. La página de devoluciones pide pruebas distintas según el problema; fotografía lo que identifica el pedido y también el defecto.", items: [["Confirma la variante pedida", "Compara color, talla, versión y cantidad antes de juzgar detalles."], ["Revisa la forma general", "Busca deformación, asimetría, paneles irregulares y proporciones distintas de la ficha."], ["Inspecciona la confección", "Amplía costuras, bordes, cierres y uniones. Pide otro ángulo si algo queda oculto."], ["Lee etiquetas y código de bolsa", "Para talla, la guía oficial pide etiqueta, código de la bolsa y explicación de dónde queda grande o pequeño."], ["Compara color y medidas", "La luz altera el color. Usa medidas publicadas y una foto con regla para dimensiones críticas."], ["Documenta el daño con contexto", "En roturas, fotografía embalaje exterior, bolsa y zona dañada antes de desechar nada."], ["Clasifica el problema", "Producto incorrecto, artículo faltante, paquete equivocado y descripción inexacta requieren imágenes y registros distintos."]], source: "Fuente revisada: política y proceso de devolución del Centro de ayuda de Hacoo · 28 de agosto de 2026." },
  shipping: { facts: [["28*", "países indicados; la lista oficial actual nombra 27"], ["15–28", "días como referencia total amplia del Centro de ayuda"], ["15–65", "días en los rangos por país de la página de envíos"]], asideLabel: "ENVÍO / VERIFICACIÓN", asideTitle: "Las páginas oficiales ofrecen más de un rango.", asideText: "El Centro de ayuda divide la entrega en 3–7 días de preparación, 7–15 de envío y 5–10 de reparto final. La web indica aparte 15–25 días para Reino Unido, Francia, Alemania e Italia; 15–30 para España; y 25–65 para otros países.", items: [["Confirma la dirección admitida", "Introduce el destino real y comprueba si el artículo y la ruta están disponibles."], ["Lee el plazo como orientación", "Ambas páginas muestran que puede cambiar; no conviertas el valor más rápido en promesa."], ["Prevé paquetes separados", "La web dice que artículos disponibles pueden enviarse antes que reservas o reposiciones del mismo pedido."], ["Compara el coste completo", "Incluye entrega, conversión de pago, impuestos aplicables y suplementos de opción."], ["Corrige pronto una dirección", "La guía oficial responsabiliza al comprador de su exactitud y pide contactar de inmediato con soporte si hay error."], ["Guarda pedido y seguimiento", "Conserva variante, estimación, estado de cada paquete y comunicaciones con soporte."]], source: "Fuentes revisadas: Shipping & Delivery de Hacoo y Centro de ayuda UE sobre plazos y zonas · 28 de agosto de 2026." },
  returns: { facts: [["15", "días tras la recepción para solicitudes aptas"], ["NO", "hay servicio de cambio según la política actual"], ["$30", "compensación máxima de envío en casos atribuidos a Hacoo"]], asideLabel: "DEVOLUCIONES / PRUEBAS", asideTitle: "Documenta el problema antes de usar el artículo.", asideText: "La guía oficial excluye algunas categorías de la devolución gratuita y avisa de que productos usados, lavados, modificados o sin etiqueta pueden rechazarse. Las condiciones del pedido son la revisión final.", items: [["Abre las condiciones del pedido", "Comprueba elegibilidad, fecha límite y pasos en las pantallas del producto y pedido."], ["Conoce exclusiones habituales", "Belleza abierta; ropa interior, baño, leggings y lencería; joyería/lujo; y electrónica indicada pueden quedar fuera de devolución gratuita."], ["Fotografía el paquete", "Captura embalaje exterior, etiqueta de envío, bolsa del producto y estado antes de tirar nada."], ["Muestra el artículo completo", "Haz una vista general y primeros planos del defecto, opción incorrecta o parte faltante."], ["Obtén aprobación antes de enviar", "La página dice que devoluciones no aprobadas pueden rechazarse y que no hay recogida actualmente."], ["Sé realista con los costes", "Si el motivo es del cliente, este puede pagar devolución/aduanas; el envío original figura como no reembolsable."], ["No esperes un cambio", "La política actual no admite cambios; otra talla puede exigir devolución y nuevo pedido."]], source: "Fuentes revisadas: política de devolución de Hacoo y ‘¿Cómo devolver los productos?’ · 28 de agosto de 2026." },
  categories: ["Calzado", "Sudaderas", "Camisetas", "Chaquetas", "Pantalones / Shorts", "Gorras y sombreros", "Accesorios", "Conjuntos cortos", "Electrónica", "Otros hallazgos", "Camisetas deportivas"],
