  spreadsheet: { searchLabel: "RICERCA CATALOGO ATTIVO", searchTitle: "Usa una frase prodotto specifica.", headingIndex: "DESTINAZIONI CATEGORIA ESATTE", headingTitle: "Apri la destinazione, non una home generica.", headingText: "Ogni scheda apre la categoria corrispondente nel catalogo principale attivo.", asideLabel: "FOGLIO / METODO", asideTitle: "Cosa questo indice può provare — e cosa no.", asideText: "I termini Hacoo attribuiscono ai creator indipendenti la responsabilità dei contenuti utente. Un foglio è quindi uno strumento di scoperta, non un’approvazione ufficiale.", items: [["Usa una destinazione esatta", "Una scheda categoria apre la categoria corrispondente; una scheda prodotto apre una singola pagina dettaglio."], ["Confronta immagine e titolo", "Non basta un URL funzionante. Prima immagine e titolo attuali devono ancora corrispondere alla scheda fonte."], ["Controlla paese e regione", "Hacoo dichiara 28 paesi supportati, ma l’elenco ufficiale attuale ne nomina 27. Verifica la disponibilità reale nell’app."], ["Mantieni visibile l’incertezza", "Data di verifica, stime USD e stato indipendente vanno etichettati, non presentati come garanzie permanenti."]], source: "Fonti verificate: Chi siamo, Termini di servizio, Centro assistenza ufficiale sulle aree di consegna e rotte del catalogo principale · 28 agosto 2026." },
  finds: { headingIndex: "DESTINAZIONI PRODOTTO ABBINATE", headingTitle: "Prima immagine, titolo e URL verificati insieme.", headingText: "Queste schede usano la prima immagine attuale della pagina esatta. Gli USD sono conversioni indicative del prezzo origine mostrato.", priceNote: "Riferimento: CN¥6,75 = US$1, verificato il 28 agosto 2026. Ricontrolla opzione, prezzo origine e totale. Se immagine o prodotto sono cambiati, non proseguire dalla scheda.", asideLabel: "SCOPERTE / VERIFICA", asideTitle: "Un piccolo catalogo può essere più utile.", asideText: "Il volume non indica qualità. Una scheda utile mantiene il rapporto tra scoperta e destinazione attiva.", items: [["Pagina dettaglio esatta", "Nessuna scheda rimanda alla home, a una ricerca generica o a un’altra piattaforma."], ["Prima immagine corrispondente", "L’immagine mostrata qui è la prima immagine prodotto della stessa destinazione."], ["Prezzo origine visibile", "La cifra CNY originale resta accanto alla stima USD."], ["Controllo opzione attuale", "La destinazione resta autorevole per colore, taglia, variante, scorte e prezzo finale."]] },
  qc: { asideLabel: "QC / 01—07", asideTitle: "Un ordine di ispezione ripetibile", asideText: "Inizia dalla vista generale e poi avvicinati. La pagina resi Hacoo richiede prove diverse secondo il problema; fotografa ciò che identifica l’ordine e il difetto.", items: [["Conferma la variante ordinata", "Confronta colore, taglia, versione e quantità prima di valutare i dettagli."], ["Controlla la forma generale", "Cerca deformazioni, asimmetria, pannelli irregolari e proporzioni diverse dall’inserzione."], ["Esamina la costruzione", "Ingrandisci cuciture, bordi, chiusure e giunzioni. Chiedi un’altra angolazione se una zona è nascosta."], ["Leggi etichetta e codice busta", "Per problemi di taglia, la guida ufficiale chiede etichetta, barcode della busta e spiegazione della vestibilità errata."], ["Confronta colore e misure", "La luce cambia il colore. Usa misure indicate e foto con righello per dimensioni critiche."], ["Documenta il danno nel contesto", "Per rotture, fotografa imballo esterno, busta e zona danneggiata prima di eliminare l’imballaggio."], ["Classifica il problema", "Prodotto errato, articolo mancante, pacco sbagliato e descrizione inesatta richiedono immagini e registri diversi."]], source: "Fonte verificata: politica e procedura resi del Centro assistenza Hacoo · 28 agosto 2026." },
  shipping: { facts: [["28*", "paesi dichiarati; 27 attualmente nominati nell’elenco ufficiale"], ["15–28", "giorni come riferimento totale ampio del Centro assistenza"], ["15–65", "giorni negli intervalli per paese della pagina spedizioni"]], asideLabel: "SPEDIZIONE / VERIFICA", asideTitle: "Le pagine ufficiali forniscono più intervalli.", asideText: "Il Centro assistenza divide 3–7 giorni di preparazione, 7–15 di spedizione e 5–10 di consegna finale. Il sito indica separatamente 15–25 giorni per Regno Unito, Francia, Germania e Italia; 15–30 per Spagna; 25–65 per altri paesi.", items: [["Conferma l’idoneità dell’indirizzo", "Inserisci la destinazione reale e controlla disponibilità di articolo e rotta."], ["Leggi il tempo come indicazione", "Entrambe le pagine mostrano che può cambiare; non trasformare il valore più rapido in promessa."], ["Prevedi pacchi separati", "Il sito dice che articoli disponibili possono partire prima di preordini o riassortimenti dello stesso ordine."], ["Confronta il costo completo", "Includi consegna, conversione pagamento, imposte applicabili e supplementi opzione."], ["Correggi subito un indirizzo", "La guida ufficiale rende l’acquirente responsabile dell’esattezza e invita a contattare subito l’assistenza in caso di errore."], ["Conserva ordine e tracciamento", "Salva variante, stima, stato di ogni pacco e comunicazioni con l’assistenza."]], source: "Fonti verificate: Hacoo Shipping & Delivery e Centro assistenza UE su tempi e aree · 28 agosto 2026." },
  returns: { facts: [["15", "giorni dal ricevimento per richieste idonee"], ["NO", "servizio di cambio secondo la politica attuale"], ["$30", "rimborso massimo spedizione nei casi attribuiti a Hacoo"]], asideLabel: "RESI / PROVE", asideTitle: "Documenta il problema prima dell’uso.", asideText: "La guida ufficiale esclude alcune categorie dal reso gratuito e dice che prodotti usati, lavati, modificati o senza etichetta possono essere rifiutati. Le regole del singolo ordine restano decisive.", items: [["Apri le condizioni dell’ordine", "Controlla idoneità, scadenza e passaggi nelle schermate prodotto e ordine."], ["Conosci le esclusioni comuni", "Beauty aperto; intimo, costumi, leggings e lingerie; gioielli/lusso; ed elettronica indicata possono essere esclusi dal reso gratuito."], ["Fotografa il pacco", "Riprendi imballo esterno, etichetta spedizione, busta prodotto e condizioni prima di buttare."], ["Mostra l’articolo completo", "Scatta una vista intera e primi piani del difetto, opzione errata o parte mancante."], ["Ottieni approvazione prima dell’invio", "La pagina dice che resi non approvati possono essere rifiutati e che il ritiro non è supportato."], ["Mantieni realistiche le aspettative sui costi", "Per motivi del cliente, spedizione reso/dogana possono restare a suo carico; le spese iniziali risultano non rimborsabili."], ["Non aspettarti un cambio", "La politica attuale non supporta cambi; un’altra taglia può richiedere reso e nuovo ordine."]], source: "Fonti verificate: politica resi Hacoo e ‘Come restituire i prodotti?’ · 28 agosto 2026." },
